<?php
if (!defined('ABSPATH')) { exit; }
function awsw_programs() { return ['food'=>['Food & ration','خوراک اور راشن','Nourishment and essential groceries for families facing hardship.','مشکل حالات سے گزرنے والے خاندانوں کے لیے خوراک اور ضروری راشن۔','✳'],'education'=>['Education','تعلیم','Learning materials and educational support that open new possibilities.','نئے امکانات کے لیے تعلیمی وسائل اور معاونت۔','↗'],'water'=>['Clean water','صاف پانی','Community-led access to safe water and healthier everyday lives.','اجتماعی کوششوں سے صاف پانی اور صحت مند زندگی تک رسائی۔','◉'],'medical'=>['Medical support','طبی معاونت','Helping people access essential treatment with care and dignity.','عزت اور ہمدردی کے ساتھ ضروری علاج تک رسائی میں مدد۔','♡']]; }
function awsw_program_name($slug) { $p = awsw_programs()[$slug] ?? null; return $p ? awsw_t($p[0],$p[1]) : ''; }
function awsw_button($text, $url, $class = '') { return '<a class="awsw-button ' . esc_attr($class) . '" href="' . esc_url($url) . '">' . esc_html($text) . '' . awsw_icon('arrow') . '</a>'; }
function awsw_empty($en, $ur) { return '<div class="awsw-empty"><span aria-hidden="true">✳</span><p>' . esc_html(awsw_t($en,$ur)) . '</p></div>'; }
function awsw_post_title($id) { return awsw_field($id, 'title', get_the_title($id)); }
function awsw_cover($id) {
    if (has_post_thumbnail($id)) { return get_the_post_thumbnail($id,'large',['loading'=>'lazy']); }
    return '<div class="awsw-photo-placeholder"><span aria-hidden="true">✳</span><small>' . esc_html(awsw_t('Approved project photograph to be added','منظور شدہ منصوبے کی تصویر جلد شامل کی جائے گی')) . '</small></div>';
}
function awsw_campaign_cards($args = []) {
    $q = new WP_Query(array_merge(['post_type'=>'awsw_campaign','post_status'=>'publish','posts_per_page'=>6],$args));
    if (!$q->have_posts()) { return awsw_empty('No campaigns are published for this selection. Please check back for verified campaign details.','اس انتخاب میں کوئی شائع شدہ مہم موجود نہیں۔ تصدیق شدہ معلومات کے لیے دوبارہ تشریف لائیں۔'); }
    $html = '<div class="awsw-grid awsw-campaigns">';
    foreach ($q->posts as $p) {
        $progress = awsw_progress($p->ID); $terms = wp_get_post_terms($p->ID,'awsw_program'); $status = get_post_meta($p->ID,'_awsw_status',true) ?: 'draft';
        $html .= '<article class="awsw-card">' . awsw_cover($p->ID) . '<div class="awsw-card-body"><span class="awsw-eyebrow">' . esc_html($terms ? awsw_program_name($terms[0]->slug) : awsw_t('Community care','اجتماعی بہبود')) . '</span><h3><a href="' . esc_url(add_query_arg('lang',awsw_lang(),get_permalink($p))) . '">' . esc_html(awsw_post_title($p->ID)) . '</a></h3><p class="awsw-small">' . esc_html(awsw_field($p->ID,'excerpt',awsw_excerpt($p))) . '</p><p>' . esc_html(awsw_t('Confirmed funds','تصدیق شدہ رقم') . ': ' . awsw_money($progress['raised'])) . '</p>';
        if ($progress['percent'] !== null) { $html .= '<progress max="100" value="' . esc_attr(min(100,$progress['percent'])) . '" aria-label="' . esc_attr(awsw_t('Fundraising progress','جمع شدہ عطیات کی شرح')) . '"></progress><p class="awsw-small">' . esc_html($progress['percent'] . '% · ' . awsw_t('Target','ہدف') . ': ' . awsw_money($progress['target'])) . '</p>'; }
        $html .= '<span class="awsw-status">' . esc_html(awsw_status_label($status)) . '</span>' . awsw_button(awsw_t('View campaign','مہم دیکھیں'),add_query_arg('lang',awsw_lang(),get_permalink($p)),'awsw-outline') . '</div></article>';
    }
    $html .= '</div>'; $pages = (int) $q->max_num_pages;
    if ($pages > 1) { $html .= '<nav class="awsw-pagination" aria-label="' . esc_attr(awsw_t('Campaign pages','مہمات کے صفحات')) . '">'; for ($i=1;$i<=$pages;$i++) { $html .= '<a href="' . esc_url(add_query_arg('campaign_page',$i)) . '" ' . ($i === max(1,(int)($args['paged']??1)) ? 'aria-current="page"' : '') . '>' . (int)$i . '</a> '; } $html .= '</nav>'; }
    return $html;
}
function awsw_status_label($s) { $map=['active'=>['Active','جاری'],'paused'=>['Paused','عارضی طور پر معطل'],'completed'=>['Completed','مکمل'],'draft'=>['Not accepting donations','عطیات قبول نہیں ہو رہے'],'pending'=>['Pending verification','تصدیق کا منتظر'],'confirmed'=>['Confirmed','تصدیق شدہ'],'rejected'=>['Rejected','مسترد'],'refunded'=>['Refunded','واپس کیا گیا']]; return isset($map[$s]) ? awsw_t(...$map[$s]) : $s; }
add_shortcode('awsw_campaigns', function () {
    $args=['paged'=>max(1,absint($_GET['campaign_page']??1))];
    if (!empty($_GET['campaign_search'])) { $args['s']=sanitize_text_field(wp_unslash($_GET['campaign_search'])); }
    if (!empty($_GET['program']) && isset(awsw_programs()[sanitize_key($_GET['program'])])) { $args['tax_query']=[['taxonomy'=>'awsw_program','field'=>'slug','terms'=>sanitize_key($_GET['program'])]]; }
    $status=sanitize_key($_GET['campaign_status']??''); if (in_array($status,['active','paused','completed'],true)) { $args['meta_key']='_awsw_status';$args['meta_value']=$status; }
    ob_start(); ?>
    <form class="awsw-filters" method="get"><input type="hidden" name="lang" value="<?php echo esc_attr(awsw_lang()); ?>"><label><?php echo esc_html(awsw_t('Search campaigns','مہم تلاش کریں')); ?><input name="campaign_search" value="<?php echo esc_attr(sanitize_text_field($_GET['campaign_search']??'')); ?>" type="search"></label><label><?php echo esc_html(awsw_t('Program','شعبہ')); ?><select name="program"><option value=""><?php echo esc_html(awsw_t('All programs','تمام شعبے')); ?></option><?php foreach (awsw_programs() as $slug=>$p) { echo '<option value="'.esc_attr($slug).'" '.selected(sanitize_key($_GET['program']??''),$slug,false).'>'.esc_html(awsw_t($p[0],$p[1])).'</option>'; } ?></select></label><label><?php echo esc_html(awsw_t('Status','حالت')); ?><select name="campaign_status"><option value=""><?php echo esc_html(awsw_t('All statuses','تمام حالتیں')); ?></option><?php foreach (['active','paused','completed'] as $s) { echo '<option value="'.esc_attr($s).'" '.selected($status,$s,false).'>'.esc_html(awsw_status_label($s)).'</option>'; } ?></select></label><button class="awsw-button"><?php echo esc_html(awsw_t('Apply filters','فلٹر لگائیں')); ?></button></form>
    <?php return ob_get_clean() . awsw_campaign_cards($args);
});
function awsw_campaign_detail($id) {
    $p=awsw_progress($id);$status=get_post_meta($id,'_awsw_status',true)?:'draft';$location=awsw_field($id,'location',get_post_meta($id,'_awsw_location',true));
    ob_start(); ?><div class="awsw-detail"><div><div class="awsw-detail-cover"><?php echo awsw_cover($id); ?></div><div class="awsw-rich-content"><?php echo apply_filters('the_content', awsw_field($id,'content',get_post_field('post_content',$id))); ?></div><h2><?php echo esc_html(awsw_t('Use of funds','رقم کا استعمال')); ?></h2><p><?php echo esc_html(awsw_field($id,'use_funds',get_post_meta($id,'_awsw_use_funds',true)) ?: awsw_t('A reviewed use-of-funds statement has not yet been published.','رقم کے استعمال کی جائزہ شدہ وضاحت ابھی شائع نہیں ہوئی۔')); ?></p><h2><?php echo esc_html(awsw_t('Project delivery milestones','منصوبے کی تکمیل کے مراحل')); ?></h2><p><?php echo esc_html(awsw_t('Delivery is reported by staff and is separate from fundraising.','عملی پیش رفت کی اطلاع عملہ دیتا ہے؛ اسے جمع شدہ رقم سے الگ سمجھیں۔')); ?></p><?php
    $milestones=awsw_field($id,'milestones',get_post_meta($id,'_awsw_milestones',true));
    if ($milestones) { echo '<ul class="awsw-timeline">';foreach(explode("\n",$milestones) as $line) { if(trim($line)) { echo '<li>'.esc_html($line).'</li>'; } }echo '</ul>'; } else { echo awsw_empty('No verified delivery milestones published yet.','ابھی تصدیق شدہ عملی مراحل شائع نہیں ہوئے۔'); }
    echo '<h2>'.esc_html(awsw_t('Dated updates & reports','تاریخ وار خبریں اور رپورٹس')).'</h2>' . awsw_updates(['meta_key'=>'_awsw_campaign','meta_value'=>$id]);
    ?></div><aside class="awsw-fund-box"><span class="awsw-status"><?php echo esc_html(awsw_status_label($status)); ?></span><h2><?php echo esc_html(awsw_money($p['raised'])); ?></h2><p><?php echo esc_html(awsw_t('Confirmed, non-refunded funds','تصدیق شدہ، غیر واپس کردہ عطیات')); ?></p><?php if($p['percent']!==null){ ?><progress max="100" value="<?php echo esc_attr(min(100,$p['percent'])); ?>" aria-label="<?php echo esc_attr(awsw_t('Fundraising progress','عطیات کی پیش رفت')); ?>"></progress><dl><dt><?php echo esc_html(awsw_t('Target','ہدف')); ?></dt><dd><?php echo esc_html(awsw_money($p['target'])); ?></dd><dt><?php echo esc_html(awsw_t('Remaining','باقی رقم')); ?></dt><dd><?php echo esc_html(awsw_money($p['remaining'])); ?></dd><dt><?php echo esc_html(awsw_t('Funded','جمع شدہ شرح')); ?></dt><dd><?php echo esc_html($p['percent'].'%'); ?></dd></dl><?php }else{echo '<p>'.esc_html(awsw_t('A fundraising target has not been published.','عطیات کا ہدف ابھی شائع نہیں ہوا۔')).'</p>';} ?>
    <?php if($location){echo '<p>'.esc_html($location).'</p>';} foreach(['start'=>['Starts','آغاز'],'end'=>['Ends','اختتام']] as $k=>$label){$v=get_post_meta($id,'_awsw_'.$k,true);if($v){echo '<p>'.esc_html(awsw_t(...$label).': '.$v).'</p>';}} ?>
    <?php if($status==='active'){echo awsw_button(awsw_t('Donate to this campaign','اس مہم کے لیے عطیہ دیں'),add_query_arg('campaign',$id,awsw_url('donate/')));}else{echo '<p>'.esc_html(awsw_t('This campaign is not accepting donations.','یہ مہم فی الحال عطیات قبول نہیں کر رہی۔')).'</p>';} ?><p class="awsw-small"><?php echo esc_html(awsw_t('Bank transfer · PKR · Staff verification required','بینک ٹرانسفر · پاکستانی روپے · عملے کی تصدیق ضروری')); ?></p></aside></div><?php
    $terms=wp_get_post_terms($id,'awsw_program',['fields'=>'ids']);echo '<h2>'.esc_html(awsw_t('Campaign questions','مہم سے متعلق سوالات')).'</h2>'.awsw_faq_items(awsw_faq_groups()['verification'][2]);echo '<section><h2>'.esc_html(awsw_t('Related campaigns','متعلقہ مہمات')).'</h2>'.awsw_campaign_cards(['post__not_in'=>[$id],'posts_per_page'=>3,'tax_query'=>$terms?[['taxonomy'=>'awsw_program','terms'=>$terms]]:[]]).'</section>';
    return ob_get_clean();
}
function awsw_form_hidden($kind) {
    wp_nonce_field('awsw_'.$kind,'_awsw_nonce');echo '<input type="hidden" name="action" value="'.($kind==='donate'?'awsw_donate':'awsw_enquiry').'"><input type="hidden" name="lang" value="'.esc_attr(awsw_lang()).'">';
    echo '<div class="awsw-trap" aria-hidden="true"><label>Leave this blank<input name="website_url" tabindex="-1" autocomplete="off"></label></div>';
}
function awsw_input($name,$label,$type='text',$required=true,$autocomplete='') { echo '<label for="awsw-'.esc_attr($name).'">'.esc_html($label).($required?' <span aria-hidden="true">*</span>':'').'</label><input id="awsw-'.esc_attr($name).'" name="'.esc_attr($name).'" type="'.esc_attr($type).'" '.($required?'required':'').' maxlength="190" '.($autocomplete?'autocomplete="'.esc_attr($autocomplete).'"':'').' '.((in_array($type,['email','tel'],true)||$name==='transfer_ref')?'dir="ltr"':'').'>'; }
function awsw_consent() {
    $privacy = get_page_by_path('privacy');
    $published = $privacy && get_post_status($privacy) === 'publish';
    echo '<label class="awsw-checkbox"><input type="checkbox" name="consent" value="1" required><span>' . esc_html(awsw_t('I agree to the use of my information to process this request, as described in the privacy notice.', 'میں رازداری کے نوٹس کے مطابق اس درخواست پر کارروائی کے لیے اپنی معلومات کے استعمال سے اتفاق کرتا/کرتی ہوں۔'));
    if ($published) { echo ' <a href="' . esc_url(awsw_url('privacy/')) . '">' . esc_html(awsw_t('Privacy notice', 'رازداری کا نوٹس')) . '</a>'; }
    echo '</span></label>';
    if (!$published) {
        echo '<details class="awsw-privacy-draft"><summary>' . esc_html(awsw_t('Read the privacy notice — draft awaiting organization review', 'رازداری کا نوٹس پڑھیں — ادارے کے جائزے کا مسودہ')) . '</summary><p>' . esc_html(awsw_t('Your form information is stored for authorized staff to process this request. Donation proofs are private. Marketing consent is separate and optional. The organization must approve contact details, retention periods and the full policy before this site launches. Do not submit sensitive information to an unapproved preview.', 'فارم کی معلومات مجاز عملے کے لیے درخواست پر کارروائی کی غرض سے محفوظ ہوتی ہیں۔ عطیات کے ثبوت نجی ہیں۔ تشہیری رضامندی الگ اور اختیاری ہے۔ اجرا سے پہلے ادارے کو رابطہ معلومات، ریکارڈ رکھنے کی مدت اور مکمل پالیسی منظور کرنا ہو گی۔ غیر منظور شدہ پیش منظر پر حساس معلومات نہ دیں۔')) . '</p></details>';
    }
}
add_shortcode('awsw_donate', function () {
    $design_preview=wp_get_environment_type()==='local' && isset($_GET['design_preview']) && $_GET['design_preview']==='1';
    if (!awsw_bank_ready() && !$design_preview) { return awsw_empty('Bank transfer donations are not available yet. The society must add verified Meezan Bank account details before submissions can open. No payment details have been invented.','بینک کے ذریعے عطیات ابھی دستیاب نہیں۔ درخواستیں کھولنے سے پہلے ادارے کو میزان بینک کی تصدیق شدہ معلومات شامل کرنا ہوں گی۔') . awsw_button(awsw_t('Contact the society','ادارے سے رابطہ کریں'),awsw_url('contact/')); }
    $token=bin2hex(random_bytes(24));ob_start(); ?>
    <?php if($design_preview&&!awsw_bank_ready()){echo '<p class="awsw-notice">'.esc_html(awsw_t('DESIGN PREVIEW — Bank details are not configured. No payment submission is enabled.','ڈیزائن پیش منظر — بینک معلومات موجود نہیں۔ ادائیگی کی درخواست دستیاب نہیں۔')).'</p>';} ?><div class="awsw-donation-layout"><form class="awsw-form" method="post" action="<?php echo esc_url(add_query_arg('lang',awsw_lang(),admin_url('admin-post.php'))); ?>" enctype="multipart/form-data">
    <?php awsw_form_hidden('donate'); ?><input type="hidden" name="submission" value="<?php echo esc_attr($token); ?>"><input type="hidden" name="signature" value="<?php echo esc_attr(hash_hmac('sha256',$token,wp_salt('nonce'))); ?>">
    <fieldset><legend>1. <?php echo esc_html(awsw_t('Choose your support','اپنا تعاون منتخب کریں')); ?></legend><label for="awsw-campaign"><?php echo esc_html(awsw_t('Campaign or general fund','مہم یا عمومی فنڈ')); ?></label><select id="awsw-campaign" name="campaign"><option value="0"><?php echo esc_html(awsw_t('General fund — where most needed','عمومی فنڈ — جہاں سب سے زیادہ ضرورت ہو')); ?></option><?php foreach(get_posts(['post_type'=>'awsw_campaign','numberposts'=>-1,'meta_key'=>'_awsw_status','meta_value'=>'active']) as $c){echo '<option value="'.(int)$c->ID.'" '.selected(absint($_GET['campaign']??0),$c->ID,false).'>'.esc_html(awsw_post_title($c->ID)).'</option>';} ?></select>
    <div class="awsw-amounts" aria-label="<?php echo esc_attr(awsw_t('Suggested amounts','تجویز کردہ رقم')); ?>"><?php foreach([1000,2500,5000] as $a){echo '<button type="button" data-awsw-amount="'.(int)$a.'">PKR '.esc_html(number_format($a)).'</button>';} ?></div><label for="awsw-amount"><?php echo esc_html(awsw_t('Amount in PKR (custom amounts welcome)','پاکستانی روپے میں رقم')); ?></label><input id="awsw-amount" name="amount" dir="ltr" type="number" inputmode="decimal" min="1" max="999999999.99" step="0.01" value="<?php echo esc_attr(awsw_start_amount()); ?>" required></fieldset>
    <fieldset><legend>2. <?php echo esc_html(awsw_t('Your details','آپ کی معلومات')); ?></legend><?php awsw_input('donor_name',awsw_t('Full name','مکمل نام'),'text',true,'name');awsw_input('donor_email',awsw_t('Email address','ای میل'),'email',true,'email');awsw_input('donor_phone',awsw_t('Phone (optional)','فون (اختیاری)'),'tel',false,'tel'); ?><label class="awsw-checkbox"><input type="checkbox" name="anonymous" value="1"><span><?php echo esc_html(awsw_t('Keep my identity private on public pages. Staff can still review my details.','عوامی صفحات پر میری شناخت ظاہر نہ کریں۔ عملہ میری معلومات دیکھ سکتا ہے۔')); ?></span></label><label class="awsw-checkbox"><input type="checkbox" name="marketing" value="1"><span><?php echo esc_html(awsw_t('Optional: I would like to receive future updates.','اختیاری: میں آئندہ معلومات حاصل کرنا چاہتا/چاہتی ہوں۔')); ?></span></label></fieldset>
    <fieldset><legend>3. <?php echo esc_html(awsw_t('Transfer, then submit for review','ٹرانسفر کریں، پھر تصدیق کے لیے بھیجیں')); ?></legend><p><?php echo esc_html(awsw_t('Make your transfer through your bank using the details alongside this form. Then enter the transaction reference.','اس فارم کے ساتھ دی گئی معلومات کے ذریعے اپنے بینک سے رقم منتقل کریں۔ پھر ٹرانزیکشن کا حوالہ درج کریں۔')); ?></p><?php awsw_input('transfer_ref',awsw_t('Bank transaction reference','بینک ٹرانزیکشن کا حوالہ')); ?>
    <?php if(awsw_private_dir()){ ?><label for="awsw-proof"><?php echo esc_html(awsw_t('Optional transfer proof (JPG, PNG or PDF, up to 5 MB)','اختیاری ٹرانسفر ثبوت (JPG، PNG یا PDF، زیادہ سے زیادہ ۵ میگابائٹ)')); ?></label><input type="file" id="awsw-proof" name="proof" accept="image/jpeg,image/png,application/pdf"><?php }else{echo '<p class="awsw-small">'.esc_html(awsw_t('Proof upload is unavailable while private storage is being configured. Your transaction reference can still be submitted for bank-statement verification.','نجی اسٹوریج کی ترتیب تک ثبوت اپلوڈ دستیاب نہیں۔ بینک اسٹیٹمنٹ سے تصدیق کے لیے ٹرانزیکشن کا حوالہ جمع کرایا جا سکتا ہے۔')).'</p>';} ?>
    <?php awsw_consent(); ?><p class="awsw-notice"><?php echo esc_html(awsw_t('Submitting this form does not confirm payment. Your donation remains pending until staff match it to the bank statement.','فارم بھیجنے سے ادائیگی کی تصدیق نہیں ہوتی۔ بینک اسٹیٹمنٹ سے ملانے تک عطیہ تصدیق کا منتظر رہے گا۔')); ?></p><button class="awsw-button" type="submit"><?php echo esc_html(awsw_t('Submit transfer for verification','ٹرانسفر تصدیق کے لیے بھیجیں')); ?></button></fieldset></form>
    <aside class="awsw-bank"><span class="awsw-eyebrow"><?php echo esc_html(awsw_t('MANUAL BANK TRANSFER','بینک ٹرانسفر')); ?></span><h2><?php echo esc_html(awsw_setting('bank_name') ?: awsw_t('Meezan Bank · setup pending','میزان بینک · ترتیب باقی ہے')); ?></h2><?php if(!awsw_bank_ready()){echo '<p>'.esc_html(awsw_t('Verified account title, account number and IBAN will appear here after organization setup.','تصدیق شدہ اکاؤنٹ کا نام، نمبر اور آئی بین ادارے کی ترتیب کے بعد یہاں آئیں گے۔')).'</p>';} ?><dl><?php foreach(['bank_title'=>['Account title','اکاؤنٹ کا نام'],'bank_account'=>['Account number','اکاؤنٹ نمبر'],'bank_iban'=>['IBAN','آئی بین'],'bank_branch'=>['Branch','برانچ']] as $key=>$label){$value=awsw_setting($key);if($value){echo '<dt>'.esc_html(awsw_t(...$label)).'</dt><dd><bdi id="'.esc_attr($key).'">'.esc_html($value).'</bdi>';if(in_array($key,['bank_account','bank_iban'],true)){echo ' <button type="button" class="awsw-copy" data-copy="'.esc_attr($key).'">'.esc_html(awsw_t('Copy','کاپی')).'</button>';}echo '</dd>';}} ?></dl><?php if(awsw_setting('bank_qr')){echo '<img class="awsw-qr" src="'.esc_url(awsw_setting('bank_qr')).'" alt="'.esc_attr(awsw_t('Organization-approved bank transfer QR','ادارے کا منظور شدہ بینک ٹرانسفر QR')).'">';} ?><p><?php echo esc_html(awsw_t('Check the recipient details in your banking app before confirming the transfer. Do not share banking passwords or OTPs.','ٹرانسفر کی تصدیق سے پہلے بینک ایپ میں وصول کنندہ کی معلومات چیک کریں۔ بینک پاس ورڈ یا OTP کسی سے شیئر نہ کریں۔')); ?></p><?php $policy = get_page_by_path('donation-policy'); if ($policy && $policy->post_status === 'publish') { ?><a href="<?php echo esc_url(awsw_url('donation-policy/')); ?>"><?php echo esc_html(awsw_t('Donation & refund policy','عطیات اور واپسی کی پالیسی')); ?></a><?php } else { ?><p class="awsw-notice"><?php echo esc_html(awsw_t('The donation and refund policy is awaiting organization review. Do not make a real transfer before the approved policy is published.', 'عطیات اور رقم کی واپسی کی پالیسی ادارے کے جائزے کی منتظر ہے۔ منظور شدہ پالیسی شائع ہونے سے پہلے حقیقی ٹرانسفر نہ کریں۔')); ?></p><?php } ?></aside></div><p class="awsw-live" role="status" aria-live="polite"></p>
    <?php return ob_get_clean();
});
add_shortcode('awsw_confirmation',function(){ $ref=sanitize_text_field($_GET['ref']??'');global $wpdb;$exists=preg_match('/^AWS-[A-F0-9]{24}$/D',$ref) ? $wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}awsw_donations WHERE reference=%s",$ref)) : false;if(!$exists){return awsw_empty('No valid submission reference was provided.','درخواست کا درست حوالہ فراہم نہیں کیا گیا۔');}return '<div class="awsw-confirmation"><span aria-hidden="true">♡</span><h2>'.esc_html(awsw_t('Transfer submission received','ٹرانسفر کی درخواست موصول ہو گئی')).'</h2><p><strong>'.esc_html(awsw_t('Submission reference','درخواست کا حوالہ')).': <bdi>'.esc_html($ref).'</bdi></strong></p><p>'.esc_html(awsw_t('Keep the reference from your submission. This page is not a payment receipt or a live status lookup. Staff will review the transfer against the bank statement. A confirmation email will follow approval when email delivery is available.','اپنی درخواست کا حوالہ محفوظ رکھیں۔ یہ صفحہ ادائیگی کی رسید یا موجودہ حالت کی جانچ نہیں ہے۔ عملہ بینک اسٹیٹمنٹ سے ٹرانسفر کی تصدیق کرے گا۔ منظوری کے بعد، ای میل دستیاب ہونے پر تصدیق بھیجی جائے گی۔')).'</p>'.awsw_button(awsw_t('Explore our work','ہمارا کام دیکھیں'),awsw_url('programs/')).'</div>';});
add_shortcode('awsw_enquiry',function($attrs){$a=shortcode_atts(['type'=>'contact'],$attrs);$kind=$a['type']==='volunteer'?'volunteer':'contact';ob_start();if(isset($_GET['awsw_notice'])&&$_GET['awsw_notice']==='saved'){echo '<p class="awsw-notice" role="status">'.esc_html(awsw_t('Thank you. Your enquiry was saved for staff review. Email notification delivery is handled separately.','شکریہ۔ آپ کی درخواست عملے کے جائزے کے لیے محفوظ ہو گئی ہے۔ ای میل کی ترسیل الگ عمل ہے۔')).'</p>';} ?>
<form class="awsw-form awsw-enquiry" action="<?php echo esc_url(add_query_arg('lang',awsw_lang(),admin_url('admin-post.php'))); ?>" method="post"><?php awsw_form_hidden($kind); ?><input type="hidden" name="kind" value="<?php echo esc_attr($kind); ?>"><?php awsw_input('name',awsw_t('Full name','مکمل نام'),'text',true,'name');awsw_input('email',awsw_t('Email address','ای میل'),'email',true,'email');awsw_input('phone',awsw_t('Phone','فون'),'tel',$kind==='volunteer','tel');if($kind==='volunteer'){awsw_input('city',awsw_t('City','شہر')); ?><label for="awsw-interests"><?php echo esc_html(awsw_t('Area of interest','دلچسپی کا شعبہ')); ?></label><select id="awsw-interests" name="interests" required><?php foreach(awsw_programs() as $slug=>$p){echo '<option value="'.esc_attr($slug).'">'.esc_html(awsw_t($p[0],$p[1])).'</option>';} ?></select><?php awsw_input('availability',awsw_t('Availability (days and hours)','دستیابی (دن اور اوقات)'));} ?><label for="awsw-message"><?php echo esc_html(awsw_t('Your message','آپ کا پیغام')); ?></label><textarea id="awsw-message" name="message" rows="5" maxlength="3000" <?php echo $kind==='contact'?'required':''; ?>></textarea><?php awsw_consent(); ?><button type="submit" class="awsw-button"><?php echo esc_html(awsw_t('Send to the team','ٹیم کو بھیجیں')); ?></button></form><?php return ob_get_clean();});
function awsw_updates($args=[]){
    $page_key=$args['awsw_page_key']??'';unset($args['awsw_page_key']);
    if($page_key){$args['paged']=max(1,absint($_GET[$page_key]??1));}
    $q=new WP_Query(array_merge(['post_type'=>['awsw_update','awsw_report'],'post_status'=>'publish','posts_per_page'=>12],$args));
    if(!$q->have_posts()){return awsw_empty('Verified updates and reports will appear here when published.','تصدیق شدہ خبریں اور رپورٹس شائع ہونے پر یہاں نظر آئیں گی۔');}
    $html='<div class="awsw-grid">';foreach($q->posts as $p){
        $html.='<article class="awsw-card"><div class="awsw-card-body"><time datetime="'.esc_attr(get_the_date('c',$p)).'">'.esc_html(get_the_date('j M Y',$p)).'</time><h3><a href="'.esc_url(add_query_arg('lang',awsw_lang(),get_permalink($p))).'">'.esc_html(awsw_post_title($p->ID)).'</a></h3><p>'.esc_html(awsw_field($p->ID,'excerpt',awsw_excerpt($p))).'</p><p>'.esc_html(awsw_field($p->ID,'period',get_post_meta($p->ID,'_awsw_period',true))).'</p>';
        if($p->post_type==='awsw_report'&&get_post_meta($p->ID,'_awsw_document',true)){$html.='<a href="'.esc_url(get_post_meta($p->ID,'_awsw_document',true)).'">'.esc_html(awsw_t('Download approved report (PDF)','منظور شدہ رپورٹ ڈاؤن لوڈ کریں (PDF)')).'</a>';}
        $html.='</div></article>';
    }$html.='</div>';
    if($page_key&&$q->max_num_pages>1){$html.='<nav class="awsw-pagination" aria-label="'.esc_attr(awsw_t('Results pages','نتائج کے صفحات')).'">';for($n=1;$n<=$q->max_num_pages;$n++){$html.='<a href="'.esc_url(add_query_arg($page_key,$n)).'" '.($n===$args['paged']?'aria-current="page"':'').'>'.$n.'</a> ';}$html.='</nav>';}
    return $html;
}
add_shortcode('awsw_updates',function($attrs){$a=shortcode_atts(['type'=>'awsw_update'],$attrs);$args=['post_type'=>in_array($a['type'],['awsw_update','awsw_report'],true)?$a['type']:'awsw_update'];$program=sanitize_key($_GET['program']??'');if(isset(awsw_programs()[$program])){$args['tax_query']=[['taxonomy'=>'awsw_program','field'=>'slug','terms'=>$program]];}$nav='<nav class="awsw-filter-links" aria-label="'.esc_attr(awsw_t('Filter by program','شعبے کے لحاظ سے فلٹر')).'"><a href="'.esc_url(remove_query_arg('program')).'">'.esc_html(awsw_t('All','تمام')).'</a>';foreach(awsw_programs() as $s=>$p){$nav.='<a href="'.esc_url(add_query_arg('program',$s)).'">'.esc_html(awsw_t($p[0],$p[1])).'</a>';}return $nav.'</nav>'.awsw_updates($args);});
add_shortcode('awsw_metrics',function(){ $html='<div class="awsw-grid">';$count=0;foreach(get_posts(['post_type'=>'awsw_metric','numberposts'=>30]) as $p){$selected_period=sanitize_text_field(wp_unslash($_GET['period']??''));if($selected_period && get_post_meta($p->ID,'_awsw_period',true)!==$selected_period){continue;}$value=get_post_meta($p->ID,'_awsw_metric_value',true);$period=get_post_meta($p->ID,'_awsw_period',true);$evidence=get_post_meta($p->ID,'_awsw_evidence',true);$editor=get_post_meta($p->ID,'_awsw_verified_by',true);if(!$value||!$period||!$evidence||!$editor||!user_can((int)$editor,'edit_post',$p->ID)){continue;}$count++;$html.='<article class="awsw-card awsw-card-body"><strong class="awsw-metric">'.esc_html($value).'</strong><h3>'.esc_html(awsw_post_title($p->ID)).'</h3><p>'.esc_html(awsw_field($p->ID,'period',$period)).'</p><span class="awsw-small">'.esc_html(awsw_t('Reviewed by an authorized content editor; evidence recorded internally.','مجاز مدیر کا جائزہ؛ ثبوت کا حوالہ ادارے کے پاس محفوظ ہے۔')).'</span></article>'; }return $count?$html.'</div>':awsw_empty('Impact figures will be published with reporting periods and evidence after review. No unverified figures are displayed.','جائزے کے بعد اثرات کے اعداد و شمار مدت اور ثبوت کے ساتھ شائع کیے جائیں گے۔ غیر تصدیق شدہ اعداد ظاہر نہیں کیے جاتے۔');});
